const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const arcticRegion = ee.Geometry.Polygon([
    [[-180, 63], [180, 63], [180, 90], [-180, 90], [-180, 63]]
  ]);

  const startDate2011 = '2011-04-01';
  const endDate2011 = '2011-04-30';
  const startDate2014 = '2014-04-01';
  const endDate2014 = '2014-04-30';

  const collectionId = 'NASA/OMI/AUR/OMTO3D'; // OMI Total Column Ozone

  // 2. Data Acquisition & Check
  const omi2011 = ee.ImageCollection(collectionId)
    .filterDate(startDate2011, endDate2011)
    .filterBounds(arcticRegion)
    .select('Ozone'); // Select the 'Ozone' band (Dobson Units)

  const omi2014 = ee.ImageCollection(collectionId)
    .filterDate(startDate2014, endDate2014)
    .filterBounds(arcticRegion)
    .select('Ozone');

  const size2011 = await omi2011.size().getInfo();
  const size2014 = await omi2014.size().getInfo();

  if (size2011 === 0 || size2014 === 0) {
    console.log(`2011 Images: ${size2011}, 2014 Images: ${size2014}`);
    console.log("C1"); // Empty Collection
    return;
  }
  console.log(`2011 Images: ${size2011}, 2014 Images: ${size2014}`);

  // 3. Processing
  // Create a mean composite for each period
  const meanOzone2011 = omi2011.mean();
  const meanOzone2014 = omi2014.mean();

  const scale = 50000; // OMI resolution is ~13x24 km, using 50km scale
  const maxPixels = 1e10; // Increase maxPixels for larger region

  // Calculate pixel count for 2011 to detect C2
  const count2011 = await meanOzone2011.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: arcticRegion,
    scale: scale,
    maxPixels: maxPixels
  }).get('Ozone').getInfo();

  if (count2011 === 0) {
    console.log("No valid pixels for 2011 after processing.");
    console.log("C2"); // No Valid Pixels
    return;
  }

  // Calculate pixel count for 2014 to detect C2
  const count2014 = await meanOzone2014.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: arcticRegion,
    scale: scale,
    maxPixels: maxPixels
  }).get('Ozone').getInfo();

  if (count2014 === 0) {
    console.log("No valid pixels for 2014 after processing.");
    console.log("C2"); // No Valid Pixels
    return;
  }
  console.log(`2011 Pixels: ${count2011}, 2014 Pixels: ${count2014}`);

  // 4. Calculation
  const meanOzoneValue2011 = await meanOzone2011.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arcticRegion,
    scale: scale,
    maxPixels: maxPixels
  }).get('Ozone').getInfo();

  const meanOzoneValue2014 = await meanOzone2014.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arcticRegion,
    scale: scale,
    maxPixels: maxPixels
  }).get('Ozone').getInfo();

  // 5. Validation & Final Answer
  if (meanOzoneValue2011 === null || meanOzoneValue2014 === null ||
      isNaN(meanOzoneValue2011) || isNaN(meanOzoneValue2014)) {
    console.log("C3"); // Calculation Failure (None or NaN result)
    return;
  }

  console.log(`April 2011 Mean Ozone (DU): ${meanOzoneValue2011.toFixed(2)}`);
  console.log(`April 2014 Mean Ozone (DU): ${meanOzoneValue2014.toFixed(2)}`);

  if (meanOzoneValue2014 > meanOzoneValue2011) {
    console.log("A"); // Yes, ozone concentration increased
  } else {
    console.log("B"); // No, ozone concentration did not increase
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
